create extension if not exists "pgcrypto";
create table profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text not null, role text not null check (role in ('adm','colaborador')), active boolean not null default true, created_at timestamptz not null default now());
create table stores (id uuid primary key default gen_random_uuid(), name text not null, slug text not null unique, active boolean not null default true, created_at timestamptz not null default now());
create table store_members (id uuid primary key default gen_random_uuid(), store_id uuid not null references stores(id) on delete cascade, user_id uuid not null references profiles(id) on delete cascade, created_at timestamptz not null default now(), unique(store_id,user_id));
create table categories (id uuid primary key default gen_random_uuid(), name text not null, icon text not null default '📦', active boolean not null default true, sort_order int not null default 0, created_at timestamptz not null default now());
create table products (id uuid primary key default gen_random_uuid(), name text not null, category_id uuid references categories(id) on delete set null, unit text not null default 'un', purchase_unit text not null default 'kg', weight_per_unit_g numeric, yield_units numeric, active boolean not null default true, created_at timestamptz not null default now());
create table inventory (id uuid primary key default gen_random_uuid(), store_id uuid not null references stores(id) on delete cascade, product_id uuid not null references products(id) on delete cascade, current_qty numeric not null default 0, min_qty numeric not null default 0, ideal_qty numeric not null default 0, updated_by uuid references profiles(id), updated_at timestamptz not null default now(), unique(store_id,product_id));
create table inventory_lists (id uuid primary key default gen_random_uuid(), store_id uuid not null references stores(id) on delete cascade, status text not null default 'aberta' check(status in ('aberta','enviada','concluida')), created_by uuid references profiles(id), created_at timestamptz not null default now(), sent_at timestamptz);
create table inventory_list_items (id uuid primary key default gen_random_uuid(), list_id uuid not null references inventory_lists(id) on delete cascade, product_id uuid not null references products(id) on delete cascade, qty_to_order numeric not null default 0, qty_to_order_kg numeric, delivered boolean not null default false, created_at timestamptz not null default now());
create table audit_logs (id uuid primary key default gen_random_uuid(), store_id uuid references stores(id) on delete set null, product_id uuid references products(id) on delete set null, user_id uuid references profiles(id) on delete set null, action text not null, old_value text, new_value text, created_at timestamptz not null default now());
create index idx_inventory_store on inventory(store_id);create index idx_inventory_product on inventory(product_id);create index idx_store_members_user on store_members(user_id);create index idx_store_members_store on store_members(store_id);create index idx_audit_logs_store on audit_logs(store_id);create index idx_audit_logs_created on audit_logs(created_at desc);create index idx_products_category on products(category_id);create index idx_list_items_list on inventory_list_items(list_id);
create or replace function calc_qty_kg(p_product_id uuid,p_qty_to_order numeric) returns numeric as $$ declare v_weight numeric; begin select weight_per_unit_g into v_weight from products where id=p_product_id; if v_weight is null then return null; end if; return round((p_qty_to_order*v_weight)/1000.0,3); end; $$ language plpgsql stable;
